import{_ as r,l,o as e,c as s,v as t,p as d,x as i,d as n,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"去渣","description":"","frontmatter":{"title":"去渣","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/descum.md","filePath":"litho/descum.md","lastUpdated":1789023840000}'),p={name:"litho/descum.md"};function c(_,a,m,u,A,B){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="去渣" tabindex="-1">去渣 <a class="header-anchor" href="#去渣" aria-label="Permalink to &quot;去渣&quot;">​</a></h1><div class="epigraph"><p>显影后的残膜和脚不是空中像的一部分；去渣用弱氧化或温和等离子体把它们清掉，也会吃掉真 CD。</p><footer>—— 对照 descum / ashing 在显影后、硬掩模开口前的公开位置</footer></div><p><a href="/litho/collapse-mitigation">上一课</a>处理还立着的线。缺口是脚下和孔底的残渣：光学上像桥、电学上开路。本课钉去渣，不把全量胶剥离提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欠显影、BARC 不溶、驻波谷，都会留残胶。SEM 上看见的「关不掉的底」若直接进主刻蚀，选择比可能不够，或把残渣当掩模打出钉。去渣过猛，线宽被吃、LER 升。把残渣全写成剂量不足，会漏掉这一步的独立窗口。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型：短时间 O₂ 或形成气体等离子体，或湿法弱氧化。终点靠时间或光学发射。须与成像胶、SOG、SOC 的选择比匹配——三层堆叠里去渣往往只清成像胶残，停在 SOG。剂量以「残渣消失、CD 损失可接受」为窗。</p>',7)),(e(),d(E,null,{default:i(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20RES%5B%22%E6%98%BE%E5%BD%B1%E5%90%8E%E6%AE%8B%E6%B8%A3%22%5D%20--%3E%20DSC%5B%22%E7%9F%AD%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%20%2F%20%E6%B9%BF%E6%B3%95%22%5D%0A%20%20DSC%20--%3E%20OPEN%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ABARC%20%2F%20%E7%A1%AC%E6%8E%A9%E6%A8%A1%E5%BC%80%E5%8F%A3%22%5D%0A%20%20DSC%20--%3E%20CD%5B%22CD%20%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">EUV 金属氧化物胶的残渣化学与 CAR 不同，同一 O₂ 去渣可能无效或过刻。换胶要重新定去渣。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>残渣薄、真图形厚，短氧化可以在真图形被明显削薄前清底。LER 的高频成分有时被「磨掉」，有时被等离子体粗糙化——要分气体。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 <a href="/litho/resist-strip-ash">胶去除</a>。去渣保留图形；剥离去掉全部掩模。下一课硬烤：去渣前后的热，改模量与残留溶剂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>去渣清显影残，付 CD 损失。</li><li>停层必须与三层选择比一致。</li><li>出处：descum 工艺通识；接续显影与倒塌课。</li></ul>',7))])}const C=r(p,[["render",c]]);export{f as __pageData,C as default};
